
  create table "public"."data_parameters" (
    "id" bigint generated by default as identity not null,
    "provider_account_id" bigint
      );



  create table "public"."temp_articles" (
    "id" bigint generated always as identity not null,
    "code" character varying(50),
    "measure" character varying(20),
    "desc" character varying(100),
    "price" numeric(18,2),
    "list_prices" jsonb
      );


alter table "public"."sales_quotes" add column "tax_num" character varying;

CREATE UNIQUE INDEX data_parameters_pkey ON public.data_parameters USING btree (id);

CREATE UNIQUE INDEX temp_articles_pkey ON public.temp_articles USING btree (id);

alter table "public"."data_parameters" add constraint "data_parameters_pkey" PRIMARY KEY using index "data_parameters_pkey";

alter table "public"."temp_articles" add constraint "temp_articles_pkey" PRIMARY KEY using index "temp_articles_pkey";

alter table "public"."data_parameters" add constraint "data_parameters_provider_account_id_fkey" FOREIGN KEY (provider_account_id) REFERENCES public.data_accounts(id) not valid;

alter table "public"."data_parameters" validate constraint "data_parameters_provider_account_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.next_document_number(p_document_id integer)
 RETURNS TABLE(letter character, point smallint, number integer)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    UPDATE data_sequences ds
    SET
        last_number = last_number + 1,
        updated_at = now()
    FROM data_documents dd
    WHERE dd.id = p_document_id
      AND ds.id = dd.data_sequence_id
    RETURNING
        ds.letter,
        ds.point,
        ds.last_number;
END;
$function$
;

